/** The eight questions: each answer's label, detail, hazard ratio and how common it is. */
val EST_Q = listOf(
    EstQ("smoke", "Do you smoke?", "People who smoke have about three times the yearly risk of death of people who never did. Quitting before 35 avoids nearly all of it.", "Jha et al., New England Journal of Medicine 2013; Thomson et al., 2021", false, listOf(EstO("Never", "Or only a handful of times", 1.0000, 0.6200), EstO("I quit before 35", "", 1.0500, 0.0600), EstO("I quit after 35", "", 1.3000, 0.1000), EstO("Yes", "Cigarettes, most days", 2.9000, 0.2200))),
    EstQ("move", "How active are you?", "About 150 minutes a week of brisk activity is linked to a third lower risk of death. Benefits start well below that.", "US Physical Activity Guidelines, 2nd ed. 2018; Zhao et al., JAMA Internal Medicine 2020", false, listOf(EstO("Rarely", "Mostly sitting", 1.0000, 0.2500), EstO("A little", "Under 2½ hours a week", 0.8000, 0.3000), EstO("Regularly", "2½ hours or more a week", 0.6700, 0.3000), EstO("Very active", "Including hard exercise", 0.6400, 0.1500))),
    EstQ("bmi", "What’s your body mass index?", "Risk is lowest around a BMI of 20 to 25 and rises steadily with obesity, and with being very underweight.", "Global BMI Mortality Collaboration, The Lancet 2016 (10.6 million people)", true, listOf(EstO("Under 18.5", "Underweight", 1.5100, 0.0700), EstO("18.5 – 25", "Healthy weight", 1.0000, 0.4200), EstO("25 – 30", "Overweight", 1.1300, 0.3200), EstO("30 – 35", "Obesity, class 1", 1.4500, 0.1200), EstO("35 – 40", "Obesity, class 2", 1.9400, 0.0500), EstO("Over 40", "Obesity, class 3", 2.7600, 0.0200))),
    EstQ("drink", "How much alcohol do you drink?", "Above about 7 drinks a week, life expectancy falls: by 4 to 5 years at over 25 drinks a week. One drink here is 14 g of alcohol: a small beer, glass of wine or shot.", "Wood et al., The Lancet 2018 (600,000 drinkers, 83 studies)", false, listOf(EstO("None, or up to 7 a week", "", 1.0000, 0.7500), EstO("7 – 14 a week", "", 1.0400, 0.1200), EstO("14 – 25 a week", "", 1.1400, 0.0800), EstO("More than 25 a week", "", 1.4700, 0.0500))),
    EstQ("diet", "What do you mostly eat?", "The healthiest diets (lots of vegetables, fruit, whole grains, nuts and legumes; little processed meat and sugar) go with about a fifth lower risk of death.", "Schwingshackl et al., Journal of the Academy of Nutrition and Dietetics 2018", false, listOf(EstO("Mostly whole foods", "Vegetables, fruit, grains, legumes, nuts", 0.7800, 0.2500), EstO("A bit of everything", "", 0.8900, 0.5500), EstO("Mostly processed or fast food", "", 1.0000, 0.2000))),
    EstQ("sleep", "How long do you usually sleep?", "Regularly sleeping under 6 hours, or over 9, is linked to higher risk of death than 7 to 8 hours.", "Cappuccio et al., Sleep 2010 (1.4 million people)", false, listOf(EstO("Under 6 hours", "", 1.1200, 0.2000), EstO("6 – 9 hours", "", 1.0000, 0.7000), EstO("9 hours or more", "", 1.3000, 0.1000))),
    EstQ("social", "Do you often feel lonely or cut off?", "Loneliness and social isolation each raise the risk of death by about a quarter, comparable to well-known risks like obesity.", "Holt-Lunstad et al., Perspectives on Psychological Science 2015", false, listOf(EstO("No, I have people around me", "", 1.0000, 0.8000), EstO("Yes, often", "", 1.2900, 0.2000))),
    EstQ("diab", "Do you have diabetes?", "Diabetes nearly doubles the yearly risk of death; at 50 that means about 6 years less on average. Good control narrows the gap.", "Emerging Risk Factors Collaboration, New England Journal of Medicine 2011", false, listOf(EstO("No", "", 1.0000, 0.9000), EstO("Yes", "Type 1 or type 2", 1.8000, 0.1000))),
